// Smart header: hides while moving down and reappears on upward scroll.
let lastScrollPosition=window.scrollY||0;
window.addEventListener('scroll',()=>{
 const y=window.scrollY||0,top=document.querySelector('.topbar');
 if(!top)return;
 if(document.body.classList.contains('mobile-open')||!document.querySelector('#profileMenu').hidden||!document.querySelector('#professorPopover').hidden||y<95){top.classList.remove('header-hidden');}
 else if(y>lastScrollPosition+5&&y>190){top.classList.add('header-hidden');}
 else if(y<lastScrollPosition-5){top.classList.remove('header-hidden');}
 lastScrollPosition=y;
},{passive:true});
