document.addEventListener('click',e=>{if(e.target.id==='saveName'){state.profile.name=(document.querySelector('#displayName').value||'Learner').trim().slice(0,50);save();settings();toast('Profile display name saved.')}if(e.target.id==='voicePlay')startAudio();if(e.target.id==='voicePause')pauseAudio();if(e.target.id==='voiceStop')stopAudio();if(e.target.id==='voiceCopy'){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(activeNarration).then(()=>toast('Narration script copied.')).catch(()=>toast('Copy unavailable.'))}else{toast('Clipboard unavailable in this browser.')}}});
